<?php foreach(documentOptions() as $key=>$label):$isRequired=in_array($key,$required,true);?><div class="upload-item"><div class="section-heading"><h3><?= e($label) ?><?= $isRequired?' <em>*</em>':' <small class="muted">Opsional</small>' ?></h3><?php if(!empty($documents[$key])):?><span class="badge green">Terunggah</span><?php endif;?></div><?php if(!empty($documents[$key])):$info=$dokumenInfo[(int)$documents[$key]]??null;?><div class="attached-file"><?= icon('file') ?><a href="<?= e(url('dokumen/lihat',['id'=>$documents[$key]])) ?>" target="_blank" rel="noopener"><?= e($info['namaAsli']??'Dokumen PDF') ?></a><small><?= $info?number_format($info['ukuran']/1024,0):'' ?> KB</small><button class="button text danger-text" name="aksiForm" value="hapus:<?= e($key) ?>" formnovalidate>Hapus</button></div><?php endif;?><label class="file-picker"><span><?= icon('download') ?> <?= empty($documents[$key])?'Pilih berkas PDF':'Ganti berkas PDF' ?></span><input type="file" name="dokumen[<?= e($key) ?>]" accept="application/pdf,.pdf"></label><?php if($key==='CV'&&$mahasiswa['idCV']):?><button class="button text" name="aksiForm" value="gunakanCV" formnovalidate>Gunakan CV dari profil</button><?php endif;?></div><?php endforeach; ?>
<label>Portofolio / Tautan Karya <?= in_array('Portofolio',$required,true)?'<em>*</em>':'<small class="muted">(Opsional)</small>' ?><input type="url" name="portofolio" maxlength="250" placeholder="https://github.com/username atau tautan portofolio" value="<?= e($draft? $draft['portofolio']:$mahasiswa['portofolio']) ?>"><small>Untuk persyaratan portofolio, pilih PDF atau isi tautan ini.</small></label><label>Surat Pengantar Singkat / Pernyataan Minat<textarea name="suratPengantar" rows="4" maxlength="6000" placeholder="Tuliskan motivasi dan relevansi keahlianmu untuk posisi ini."><?= e($draft? $draft['suratPengantar']:'') ?></textarea><small>Maksimal 500 kata.</small></label><button class="button secondary" name="aksiForm" value="unggah" formnovalidate><?= icon('download') ?> Simpan &amp; Periksa Berkas</button></section></div>
<aside class="stack sticky-aside"><section class="card"><div class="section-heading"><h3>KELENGKAPAN PERSYARATAN</h3><strong><?= $filled ?>/<?= count($required) ?></strong></div><progress value="<?= $filled ?>" max="<?= max(1,count($required)) ?>"></progress><ul class="checklist"><?php foreach($required as $key):$ok=!empty($documents[$key])||$key==='Portofolio'&&!empty($draft['portofolio']);?><li class="<?= $ok?'complete':'' ?>"><?= icon($ok?'check':'clock') ?><?= e(documentOptions()[$key]??$key) ?></li><?php endforeach;?></ul><small class="muted">Klik Simpan &amp; Periksa Berkas untuk memperbarui kelengkapan.</small></section><section class="card"><h3>ALUR SELEKSI LOWONGAN</h3><ol class="vertical-timeline compact"><?php foreach($tahapan as $t):?><li><span><?= e($t['urutan']) ?></span><div><h4><?= e($t['namaTahap']) ?></h4><p><?= e($t['keterangan']) ?></p></div></li><?php endforeach;?></ol></section><section class="card"><label class="check-card consent"><input type="checkbox" name="persetujuan" value="1"<?= checked(post('persetujuan')==='1') ?>><span>Saya menyatakan bahwa seluruh data dan dokumen yang dikirim benar, akurat, dan sesuai persyaratan lowongan.</span></label><button class="button full" name="aksiForm" value="kirim">Kirim Lamaran <?= icon('arrow') ?></button><div class="actions"><button class="button secondary" name="aksiForm" value="draf" formnovalidate>Simpan Draf</button><a class="button text" href="<?= e(url('lowongan/detail',['id'=>$lowongan['idLowongan']])) ?>">Batal</a></div></section></aside></form>
